/**
 * A room/phase completion that's been observed but not yet resolved into point awards - either
 * waiting on the rest of the party's damage reports, or not checked yet. Only one of these is
 * ever open at a time; rooms/phases complete minutes apart.
 */
@Getter
@AllArgsConstructor
class PendingRoomPhase
{

	private final RaidRoom room;
	private final int phase;
	private final int roomPoints;
	private final boolean finalRoom;
	private final Set<String> roster;
	private final int fallbackLocalDamage;
	private final int fallbackObservedDamage;

	private int ticksRemaining;

	void countDownTick()
	{
		ticksRemaining--;
	}

}

package com.duckblade.osrs.tfa.features.pointstracker;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
class PlayerPointsLedger
{

	private static final int FLOOR = -50;

	private final Map<String, Integer> totals = new HashMap<>();
	private int unattributed;

	void adjust(String player, int delta)
	{
		int current = totals.getOrDefault(player, 0);
		int next = Math.max(FLOOR, current + delta);
		totals.put(player, next);
		log.debug("{} {}{} -> {}", player, delta >= 0 ? "+" : "", delta, next);
	}

	void addUnattributed(int amount)
	{
		unattributed += amount;
		log.debug("unattributed +{} -> {}", amount, unattributed);
	}

	int getUnattributed()
	{
		return unattributed;
	}

	int getTotal(String player)
	{
		return totals.getOrDefault(player, 0);
	}

	int getTeamTotal()
	{
		int sum = unattributed;
		for (int v : totals.values())
		{
			sum += v;
		}
		return sum;
	}

	void reset()
	{
		totals.clear();
		unattributed = 0;
	}

}

package com.duckblade.osrs.tfa.features.pointstracker;

import com.duckblade.osrs.tfa.TfaConfig;
import com.duckblade.osrs.tfa.module.PluginLifecycleComponent;
import com.duckblade.osrs.tfa.util.RaidRoom;
import com.duckblade.osrs.tfa.util.RaidState;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

@Singleton
public class PointsOverlay
	extends OverlayPanel
	implements PluginLifecycleComponent
{

	private final TfaConfig config;
	private final PointsTracker pointsTracker;

	@Inject
	public PointsOverlay(
		TfaConfig config,
		PointsTracker pointsTracker
	)
	{
		this.config = config;
		this.pointsTracker = pointsTracker;

		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
	}

	@Override
	public boolean isEnabled(TfaConfig config, RaidState raidState)
	{
		switch (config.pointsTrackerOverlayEnableMode())
		{
			case ALWAYS:
				return raidState.isInRaid();

			case TREASURE_ROOM_ONLY:
				return raidState.getCurrentRoom() == RaidRoom.LOOT;

			default:
				return false;
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().add(
			TitleComponent.builder()
				.text("TFA Points" + (!pointsTracker.isAccurate() ? " (Non-Party!)" : ""))
				.color(pointsTracker.isAccurate() ? Color.GREEN : Color.YELLOW)
				.build()
		);

		if (config.pointsTrackerShowTeamPoints())
		{
			addPointsLine("Total:", pointsTracker.getTeamPoints());
		}
		if (config.pointsTrackerShowPersonalPoints())
		{
			addPointsLine("Personal:", pointsTracker.getPersonalPoints());
		}

		if (config.pointsTrackerShowTeamUniqueChance())
		{
			addChanceLine("Team Unique:", pointsTracker.getTeamUniqueChance());
		}
		if (config.pointsTrackerShowPersonalUniqueChance())
		{
			addChanceLine("Personal Unique:", pointsTracker.getPersonalUniqueChance());
		}

		return super.render(graphics);
	}

	private void addLine(String left, String right)
	{
		panelComponent.getChildren().add(
			LineComponent.builder()
				.left(left)
				.right(right)
				.build()
		);
	}

	private void addPointsLine(String title, int value)
	{
		addLine(title, PointsTracker.POINTS_FORMAT.format(value));
	}

	private void addChanceLine(String title, double value)
	{
		addLine(title, PointsTracker.PERCENT_FORMAT.format(value));
	}
}

