import com.duckblade.osrs.tfa.util.RaidRoom;
import lombok.Value;

@Value
class RoomPhase
{

	RaidRoom room;
	int phase;

}

package com.duckblade.osrs.tfa.features.pointstracker;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * Splits roomPoints across the players proportionally based on roomDamage.
 * Due to integer truncation there might be extra points remaining unassigned,
 * so those get dished out based on largest-remainder first.
 */
class RoomPointsApportioner
{

	private static final Comparator<Share> COMPARATOR =
		Comparator.comparingInt(Share::getRemainder) // smallest remainder first
			.reversed() // highest remainder first
			.thenComparing(Share::getName); // then lexicographic name

	static Map<String, Integer> apportion(int roomPoints, Map<String, Integer> damageByName)
	{
		int totalDamage = 0;
		for (int damage : damageByName.values())
		{
			totalDamage += damage;
		}

		Map<String, Integer> result = new HashMap<>();
		if (totalDamage <= 0)
		{
			for (String name : damageByName.keySet())
			{
				result.put(name, 0);
			}
			return result;
		}

		List<Share> shares = new ArrayList<>(damageByName.size());
		int flooredSum = 0;
		for (Map.Entry<String, Integer> entry : damageByName.entrySet())
		{
			int numerator = roomPoints * entry.getValue();
			int floor = numerator / totalDamage;
			int remainder = numerator % totalDamage;
			shares.add(new Share(entry.getKey(), floor, remainder));
			flooredSum += floor;
		}

		shares.sort(COMPARATOR);

		int remaining = roomPoints - flooredSum;
		for (int i = 0; i < shares.size(); i++)
		{
			Share share = shares.get(i);
			result.put(share.name, share.floor + (i < remaining ? 1 : 0));
		}

		return result;
	}

	@Value
	private static class Share
	{
		String name;
		int floor;
		int remainder;
	}

}

package com.duckblade.osrs.tfa.features.pointstracker;

import com.duckblade.osrs.tfa.util.RaidRoom;
import com.google.gson.annotations.SerializedName;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.client.party.messages.PartyMemberMessage;

@Getter
public class TfaDamageMessage extends PartyMemberMessage
{

	@SerializedName("r")
	private final RaidRoom room;

	@SerializedName("p")
	private final int phase;

	// buncha ugly backwards compat stuff from centralized phase tracking
	// todo remove this on the next game update, but keep "P" serial
	@SerializedName("P")
	@Getter(AccessLevel.NONE)
	private final Integer phaseNew;

	@SerializedName("d")
	private final int damage;

	public TfaDamageMessage(RaidRoom room, int phase, int damage)
	{
		this.room = room;
		this.phase = (this.room != RaidRoom.OCELLUS) ? 0 : phase;
		this.phaseNew = phase;
		this.damage = damage;
	}

	public int getPhase()
	{
		if (phaseNew != null)
		{
			return phaseNew;
		}

		return room == RaidRoom.OCELLUS ? phase : 1;
	}
}

package com.duckblade.osrs.tfa.features.resupply;

import com.duckblade.osrs.tfa.TfaConfig;
import com.duckblade.osrs.tfa.module.PluginLifecycleComponent;
import com.duckblade.osrs.tfa.util.RaidRoom;
import com.duckblade.osrs.tfa.util.RaidState;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class BuyMenuSwapper
	implements PluginLifecycleComponent
{

	private static final String ENTRY_SELECT = "Select";

	@Override
	public boolean isEnabled(TfaConfig config, RaidState raidState)
	{
		return config.resupplyBuyMenuSwap() && raidState.getCurrentRoom() == RaidRoom.ARCHIVE_GUARDIAN;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded e)
	{
		if (e.getMenuEntry().getOption().equals(ENTRY_SELECT))
		{
			e.getMenuEntry().setDeprioritized(true);
		}
	}
}

package com.duckblade.osrs.tfa.features.resupply;

import com.duckblade.osrs.tfa.TfaConfig;
import com.duckblade.osrs.tfa.module.PluginLifecycleComponent;
