	{
		chatMessageManager.queue(QueuedMessage.builder()
			.name("")
			.sender("TFA Plugin")
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(label + ": " + ColorUtil.wrapWithColorTag(TimeFormat.precise(ticks), Color.red))
			.build());
	}

}

