package com.duckblade.osrs.tfa.util;

import com.duckblade.osrs.tfa.module.PluginLifecycleComponent;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class AutocastTracker
	implements PluginLifecycleComponent
{

	public static final int COM_MODE_CASTING = 4;

	private final Client client;
	private final ClientThread clientThread;

	@Getter
	private volatile Spell lastKnownAutocastSpell = Spell.UNKNOWN;

	@Override
	public void startUp()
	{
		reset();
		clientThread.invokeLater(() ->
		{
			trackCastingSpell();
			trackNonCastingStaff();
		});
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		if (e.getVarpId() == VarPlayerID.COM_MODE || e.getVarbitId() == VarbitID.AUTOCAST_SPELL)
		{
			trackCastingSpell();
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		trackNonCastingStaff();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGIN_SCREEN)
		{
			reset();
		}
	}

	private void trackCastingSpell()
	{
		if (client.getGameState() != GameState.LOGGED_IN ||
			client.getVarpValue(VarPlayerID.COM_MODE) != COM_MODE_CASTING)
		{
			return;
		}

		Spell newValue = Spell.forVarbitValue(client.getVarbitValue(VarbitID.AUTOCAST_SPELL));
		if (lastKnownAutocastSpell != newValue)
		{
			lastKnownAutocastSpell = newValue;
			log.debug("tracked autocast spell {}", lastKnownAutocastSpell);
		}
	}

	private void trackNonCastingStaff()
	{
		if (client.getGameState() != GameState.LOGGED_IN ||
			client.getVarpValue(VarPlayerID.COM_MODE) == COM_MODE_CASTING)
		{
			return;
		}

		if (lastKnownAutocastSpell != Spell.NONE && StaffUtil.isWieldingAutocastWeapon(client))
		{
			log.debug("clearing autocast spell");
			lastKnownAutocastSpell = Spell.NONE;
		}
	}

	private void reset()
	{
		lastKnownAutocastSpell = Spell.UNKNOWN;
	}
}

package com.duckblade.osrs.tfa.util;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

public class InventoryUtil
{

	public static boolean containsAny(Client client, Set<Integer> ids)
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		return containsAny(inv, ids);
	}

	public static boolean containsAny(ItemContainer inv, Set<Integer> ids)
	{
		if (inv == null)
		{
			return false;
		}

		for (Item item : inv.getItems())
		{
			if (ids.contains(item.getId()))
			{
				return true;
			}
		}

		return false;
	}

}

package com.duckblade.osrs.tfa.util;

import java.awt.Polygon;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;

public class PolygonUtil
{

	public static Polygon mirror(Polygon poly, boolean flipX, boolean flipY)
	{
		Polygon ret = new Polygon(new int[poly.npoints], new int[poly.npoints], poly.npoints);
		for (int i = 0; i < poly.npoints; i++)
		{
			ret.xpoints[i] = flipX ? -poly.xpoints[i] : poly.xpoints[i];
			ret.ypoints[i] = flipY ? -poly.ypoints[i] : poly.ypoints[i];
		}
		return ret;
	}

	public static Polygon localPointTranspose(LocalPoint localOrigin, Polygon poly)
	{
		Polygon ret = new Polygon(new int[poly.npoints], new int[poly.npoints], poly.npoints);
		for (int i = 0; i < poly.npoints; i++)
		{
			ret.xpoints[i] = localOrigin.getX() + poly.xpoints[i];
			ret.ypoints[i] = localOrigin.getY() + poly.ypoints[i];
		}
		return ret;
	}

	public static Polygon toCanvas(Client client, int z, Polygon poly)
	{
		Polygon ret = new Polygon(new int[poly.npoints], new int[poly.npoints], poly.npoints);
		for (int i = 0; i < poly.npoints; i++)
		{
			Point canvas = Perspective.localToCanvas(client, poly.xpoints[i], poly.ypoints[i], z);
			if (canvas == null)
			{
				return null;
			}

			ret.xpoints[i] = canvas.getX();
			ret.ypoints[i] = canvas.getY();
		}
		return ret;
	}

}

package com.duckblade.osrs.tfa.util;

import com.duckblade.osrs.tfa.module.PluginLifecycleComponent;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RaidCompletionTracker
	implements PluginLifecycleComponent
{

	private final Set<String> completedBosses = new HashSet<>();

	@Override
	public void startUp()
	{
		completedBosses.clear();
	}

	@Subscribe(priority = Float.MAX_VALUE)
	public void onChatMessage(ChatMessage e)
	{
		if (e.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(e.getMessage());
		if (message.startsWith("Challenge complete: "))
		{
			String bossName = message.substring("Challenge complete: ".length(), message.indexOf('.'));
			completedBosses.add(bossName);
		}
	}

	@Subscribe
	public void onRaidStateChanged(RaidStateChanged e)
	{
		if (!e.getNewState().isInRaid())
		{
			completedBosses.clear();
		}
	}

	public Set<String> getCompletedBosses()
	{
		return Collections.unmodifiableSet(completedBosses);
	}

	public int getCompletedCount()
	{
		return completedBosses.size();
	}

}

package com.duckblade.osrs.tfa.util;

import com.google.common.collect.ImmutableMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ObjectID;

@RequiredArgsConstructor
@Getter
public enum RaidDoor
{

	EZEKIEL(ObjectID.TFA_NEXUS_SECTION1_DOOR_WEST_SLIGHTLY_OPENED),
	DREADNOTH(ObjectID.TFA_NEXUS_SECTION2_DOOR_EAST_SLIGHTLY_OPENED),
	DAGONHAI(ObjectID.TFA_NEXUS_SECTION3_DOOR_WEST_SLIGHTLY_OPENED),
	XARTH(ObjectID.TFA_NEXUS_SECTION3_DOOR_EAST_SLIGHTLY_OPENED),
	OCELLUS(ObjectID.TFA_NEXUS_OCELLUS_DOOR_OPEN),
	;

	private static final Map<Integer, RaidDoor> BY_OBJECT_ID = indexByObjectId();

	private final int objectId;

	@Nullable
	public static RaidDoor forObjectId(int objectId)
	{
		return BY_OBJECT_ID.get(objectId);
	}

	private static Map<Integer, RaidDoor> indexByObjectId()
	{
		ImmutableMap.Builder<Integer, RaidDoor> index = ImmutableMap.builder();
		for (RaidDoor door : values())
		{
			index.put(door.objectId, door);
		}
		return index.build();
	}
}

package com.duckblade.osrs.tfa.util;

import com.duckblade.osrs.tfa.TfaConfig;
import com.duckblade.osrs.tfa.module.PluginLifecycleComponent;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RaidDoorTracker
	implements PluginLifecycleComponent
{

	private final Client client;

	private final Map<RaidDoor, GameObject> doors = new ConcurrentHashMap<>();

	@Override
	public boolean isEnabled(TfaConfig config, RaidState raidState)
	{
		return raidState.getCurrentRoom() == RaidRoom.ARCHIVE_GUARDIAN;
	}

	@Override
	public void shutDown()
	{
		doors.clear();
	}

	@Nullable
	public GameObject getDoor(RaidDoor door)
	{
		return doors.get(door);
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned e)
	{
		GameObject object = e.getGameObject();
		RaidDoor door = RaidDoor.forObjectId(object.getId());
		if (door == null)
		{
			return;
		}

		int currentPlane = client.getTopLevelWorldView().getPlane();
		if (object.getPlane() != currentPlane)
		{
			log.trace("ignoring {} door spawn {} on plane {} (current plane {})", door, object.getId(), object.getPlane(), currentPlane);
			return;
		}

		log.debug("tracking {} door spawn {} at {}", door, object.getId(), object.getWorldLocation());
		doors.put(door, object);
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned e)
	{
		doors.values().remove(e.getGameObject());
	}
}

