import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RaidFolder
	implements PluginLifecycleComponent
{

	private static final DateTimeFormatter FOLDER_NAME_FORMAT = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

	private final TfaPlugin plugin;

	@Getter
	private Filepath path;

	@Override
	public boolean isEnabled(TfaConfig config, RaidState raidState)
	{
		return raidState.isInRaid();
	}

	@Override
	public void startUp()
	{
		try
		{
			path = plugin.getDataDirectory().join(FOLDER_NAME_FORMAT.format(LocalDateTime.now()));
		}
		catch (IOException ex)
		{
			log.warn("Failed to resolve the plugin data directory", ex);
		}
	}

	@Override
	public void shutDown()
	{
		// TimeTracker reports runs ending by leaving the raid at a higher priority than ComponentManager, and needs the path
		path = null;
	}

}

package com.duckblade.osrs.tfa.util;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum RaidRoom
{

	ARCHIVE_GUARDIAN(new int[]{16471}, "Archive Guardian", "Guardian"),
	EZEKIEL(new int[]{16214}, "Ezekiel", "Ezekiel"),
	BORK(new int[]{16727}, "Bork", "Bork"),
	MOIA(new int[]{16216}, "Moia", "Moia"),
	DREADNOTH(new int[]{16728}, "Dreadnoth the Jellied", "Dreadnoth"),
	DAGONHAI(new int[]{16215}, "Dagon'hai Elder", "Dagon'hai"),
	XARTH(new int[]{16726}, "Xarth", "Xarth"),
	OCELLUS(new int[]{16472}, "Ocellus", "Ocellus"),
	LOOT(new int[]{16474}, "Loot", "Loot"),
	;

	public static final int BOSSES_PER_RAID = 5;

	private final int[] regionIds;

	@Getter
	private final String displayName;

	@Getter
	private final String shortName;

	public boolean isBossRoom()
	{
		return this != LOOT;
	}

	public static RaidRoom forRegionId(int region)
	{
		for (RaidRoom r : RaidRoom.values())
		{
			for (int regionId : r.regionIds)
			{
				if (regionId == region)
				{
					return r;
				}
			}
		}

		return null;
	}

	public static RaidRoom forString(String roomName)
	{
		for (RaidRoom r : RaidRoom.values())
		{
			if (r.getDisplayName().equals(roomName))
			{
				return r;
			}
		}

		return null;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.duckblade.osrs.tfa.util;

import lombok.Builder;
import lombok.Value;
import lombok.With;

@Value
@Builder
@With
public class RaidState
{

	boolean inLobby;
	boolean inRaid;
	RaidRoom currentRoom;
	int phase;
	int playerCount;
	boolean spectator;
	boolean practice;

	public boolean isRaiding()
	{
		return inRaid && !spectator && !practice;
	}

}

package com.duckblade.osrs.tfa.util;

import lombok.Value;

@Value
public class RaidStateChanged
{

	RaidState previousState;
	RaidState newState;

	public boolean isPhaseCompleted()
	{
		return newState.isInRaid() &&
			previousState.getCurrentRoom() != null &&
			previousState.getCurrentRoom() == newState.getCurrentRoom() &&
			previousState.getPhase() != newState.getPhase() &&
			previousState.getPhase() != RaidStateTracker.PHASE_UNSTARTED;
	}

}

package com.duckblade.osrs.tfa.util;

import com.duckblade.osrs.tfa.module.PluginLifecycleComponent;
import com.google.common.collect.ImmutableSet;
import java.util.Collections;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.annotations.VarCStr;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.VarClientStrChanged;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RaidStateTracker
	implements PluginLifecycleComponent
{

	public static final int PHASE_UNSTARTED = 0;
	public static final int PHASE_COMPLETED = 5;

	private static final int REGION_LOBBY = 16470;

	private static final int ENTER_DEBOUNCE_TICKS = 5;
	private static final int LEAVE_DEBOUNCE_TICKS = 3;

	private static final String MESSAGE_ROOM_STARTED = "Challenge started: ";
	private static final String MESSAGE_ROOM_FINISHED = "Challenge complete";

	private static final ImmutableSet<Integer> PLAYER_NAME_VARCS = ImmutableSet.of(
		VarClientID.TFA_CLIENT_NAME0,
		VarClientID.TFA_CLIENT_NAME1,
		VarClientID.TFA_CLIENT_NAME2,
		VarClientID.TFA_CLIENT_NAME3,
		VarClientID.TFA_CLIENT_NAME4,
		VarClientID.TFA_CLIENT_NAME5,
		VarClientID.TFA_CLIENT_NAME6,
		VarClientID.TFA_CLIENT_NAME7
	);

	private static final RaidState DEFAULT_STATE = RaidState.builder()
		.inLobby(false)
		.inRaid(false)
		.currentRoom(null)
		.phase(PHASE_UNSTARTED)
		.playerCount(0)
		.spectator(false)
		.practice(false)
		.build();

	private final Client client;
	private final EventBus eventBus;
	private final RaidCompletionTracker raidCompletionTracker;

	@Getter
	private volatile RaidState currentState = DEFAULT_STATE;

	@Getter
	private volatile Set<String> raidMemberNames = Collections.emptySet();

	// delay changes to inRaid to give time for raidMemberNames to update
	private boolean debouncedInRaid = false;
	private int debounceTicks = 0;
	private int phase;
	private int ocellusQuadrantDestructs;

	@Override
	public void startUp()
	{
		rebuildRaidMemberNames();
		phase = PHASE_UNSTARTED;
	}

	@Subscribe(priority = 5)
	public void onGameTick(GameTick e)
	{
		LocalPoint lp = client.getLocalPlayer().getLocalLocation();
		int region = lp == null ? -1 : WorldPoint.fromLocalInstance(client, lp).getRegionID();

		Widget w = client.getWidget(InterfaceID.TfaHud.UNIVERSE);

		RaidRoom room = RaidRoom.forRegionId(region);
		boolean inRaidRaw = room != null || (w != null && !w.isHidden());

		if (inRaidRaw == debouncedInRaid)
		{
			debounceTicks = 0;
		}
		else
		{
			debounceTicks++;
			int required = inRaidRaw ? ENTER_DEBOUNCE_TICKS : LEAVE_DEBOUNCE_TICKS;
			if (debounceTicks >= required)
			{
				debouncedInRaid = inRaidRaw;
				debounceTicks = 0;
			}
		}

		// 0 = alive
		// 1 = dead but part of raid
		// 2 = third party spectator
		boolean spectator = client.getVarbitValue(VarbitID.TFA_CLIENT_SPECTATE_MODE) >= 2;

		boolean practice = false; // todo

		if (room != null && currentState.getCurrentRoom() != room)
		{
			// don't use updatePhase in here, it would duplicate the event
			switch (room)
			{
				case ARCHIVE_GUARDIAN:
					phase = raidCompletionTracker.getCompletedCount();
					break;

				case OCELLUS:
					ocellusQuadrantDestructs = 0;
					phase = PHASE_UNSTARTED;
					break;

				default:
					phase = PHASE_UNSTARTED;
					break;
			}
		}

		setRaidState(
			RaidState.builder()
				.inLobby(region == REGION_LOBBY)
				.inRaid(debouncedInRaid)
				.currentRoom(room)
				.phase(phase)
				.playerCount(countPlayers())
				.spectator(spectator)
				.practice(practice)
				.build(),
			false
		);
	}

	public int getPlayerCount()
	{
		return this.currentState.getPlayerCount();
	}

	@Subscribe
	public void onVarClientStrChanged(VarClientStrChanged e)
	{
		if (!PLAYER_NAME_VARCS.contains(e.getIndex()))
		{
			return;
		}

		rebuildRaidMemberNames();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		switch (e.getGameState())
		{
			case LOGGING_IN:
			case HOPPING:
				debouncedInRaid = false;
				debounceTicks = 0;
				ocellusQuadrantDestructs = 0;
				phase = PHASE_UNSTARTED;
				setRaidState(DEFAULT_STATE, true);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (e.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(e.getMessage());
		if (message.startsWith(MESSAGE_ROOM_STARTED))
		{
			updatePhase(1);
		}
		else if (message.startsWith(MESSAGE_ROOM_FINISHED))
		{
			updatePhase(PHASE_COMPLETED);
		}
	}

	@Subscribe
	public void onNpcChanged(NpcChanged e)
	{
		if (e.getNpc().getId() == NpcID.TFA_OCELLUS_P2)
		{
			updatePhase(2);
		}
		else if (e.getNpc().getId() == NpcID.TFA_OCELLUS_P3)
		{
			updatePhase(3);
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged e)
	{
		if (!(e.getActor() instanceof NPC) ||
			((NPC) e.getActor()).getId() != NpcID.TFA_OCELLUS_P3)
		{
			return;
		}

		if (e.getActor().getAnimation() == AnimationID.NPC_OCELLUS_QUADRANT_DESTROY_IN)
		{
			ocellusQuadrantDestructs++;
			if (ocellusQuadrantDestructs == 3)
			{
				updatePhase(4);
			}
		}
	}

	private void rebuildRaidMemberNames()
	{
		ImmutableSet.Builder<String> names = ImmutableSet.builder();

		// the game clears these back to "" at the start of every raid, so an empty value is
		// never a stale leftover from a previous (larger) raid - it genuinely means no player
		for (@VarCStr int varc : PLAYER_NAME_VARCS)
		{
			String name = client.getVarcStrValue(varc);
			if (name != null && !name.isEmpty())
			{
				names.add(Text.toJagexName(name));
			}
		}

		raidMemberNames = names.build();
	}

	private void setRaidState(RaidState newValue, boolean forceEvent)
	{
		RaidState previous = currentState;
		currentState = newValue;

		if (forceEvent || !currentState.equals(previous))
		{
			eventBus.post(new RaidStateChanged(previous, currentState));
		}
	}

	private int countPlayers()
	{
		return 1 +
			(client.getVarbitValue(VarbitID.TFA_CLIENT_P1) != 0 ? 1 : 0) +
			(client.getVarbitValue(VarbitID.TFA_CLIENT_P2) != 0 ? 1 : 0) +
			(client.getVarbitValue(VarbitID.TFA_CLIENT_P3) != 0 ? 1 : 0) +
			(client.getVarbitValue(VarbitID.TFA_CLIENT_P4) != 0 ? 1 : 0) +
			(client.getVarbitValue(VarbitID.TFA_CLIENT_P5) != 0 ? 1 : 0) +
			(client.getVarbitValue(VarbitID.TFA_CLIENT_P6) != 0 ? 1 : 0) +
			(client.getVarbitValue(VarbitID.TFA_CLIENT_P7) != 0 ? 1 : 0);
	}

	private void updatePhase(int phase)
	{
		// thin wrapper around phase-setter + event emit.
		// used to avoid waiting for a new GameTick to publish a phase event,
		// since event ordering matters in PointsTracker.
		this.phase = phase;
		if (currentState.getPhase() != phase)
		{
			setRaidState(
				currentState.withPhase(phase),
				false
			);
		}
	}
}

package com.duckblade.osrs.tfa.util;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum Spell
{

	// only listing spells that are relevant to the raid

	/** explicitly not on autocast */
	NONE(0),

	/** any irrelevant spell */
	OTHER(-1),

	/** the client has not seen the player's autocast yet, e.g. they logged in and have not wielded a castable staff since */
	UNKNOWN(-2), //

	// Standard
	WIND_STRIKE(1),
	WATER_STRIKE(2),
	EARTH_STRIKE(3),
	WIND_BOLT(5),
	WATER_BOLT(6),
	EARTH_BOLT(7),
	WIND_BLAST(9),
	WATER_BLAST(10),
	EARTH_BLAST(11),
	WIND_WAVE(13),
	WATER_WAVE(14),
	EARTH_WAVE(15),
	WIND_SURGE(48),
	WATER_SURGE(49),
	EARTH_SURGE(50),

	// Ancient
	ICE_RUSH(34),
	SMOKE_BURST(35),
	SHADOW_BURST(36),
	BLOOD_BURST(37),
	ICE_BURST(38),
	ICE_BLITZ(42),
	SMOKE_BARRAGE(43),
	SHADOW_BARRAGE(44),
	BLOOD_BARRAGE(45),
	ICE_BARRAGE(46),

	// Arceuus
	GHOSTLY_GRASP(56),
	SKELETAL_GRASP(57),
	UNDEAD_GRASP(58),
	;

	public static final Set<Spell> AIR_SPELLS = ImmutableSet.of(
		WIND_STRIKE,
		WIND_BOLT,
		WIND_BLAST,
		WIND_WAVE,
		WIND_SURGE
	);

	public static final Set<Spell> WATER_SPELLS = ImmutableSet.of(
		WATER_STRIKE,
		WATER_BOLT,
		WATER_BLAST,
		WATER_WAVE,
		WATER_SURGE
	);

	public static final Set<Spell> EARTH_SPELLS = ImmutableSet.of(
		EARTH_STRIKE,
		EARTH_BOLT,
		EARTH_BLAST,
		EARTH_WAVE,
		EARTH_SURGE
	);

	public static final Set<Spell> ICE_SPELLS = ImmutableSet.of(
		ICE_RUSH,
		ICE_BURST,
		ICE_BLITZ,
		ICE_BARRAGE
	);

	public static final Set<Spell> AOE_SPELLS = ImmutableSet.of(
		SMOKE_BURST,
		SHADOW_BURST,
		BLOOD_BURST,
		ICE_BURST,
		SMOKE_BARRAGE,
		SHADOW_BARRAGE,
		BLOOD_BARRAGE,
		ICE_BARRAGE
	);

	public static final Set<Spell> GRASP_SPELLS = ImmutableSet.of(
		GHOSTLY_GRASP,
		SKELETAL_GRASP,
		UNDEAD_GRASP
	);

	@Getter
	private final int varbitValue;

	public static Spell forVarbitValue(int varbitValue)
	{
		for (Spell spell : values())
		{
			if (spell != OTHER && spell.varbitValue == varbitValue)
			{
				return spell;
			}
		}

		return OTHER;
	}
}

package com.duckblade.osrs.tfa.util;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumID;
import net.runelite.api.ParamID;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

public class StaffUtil
{

	public static final int SPELLBOOK_STANDARD = 0;
	public static final int SPELLBOOK_ANCIENT = 1;
	public static final int SPELLBOOK_ARCEUUS = 3;

	private static final String CASTING_STYLE_NAME = "Casting";

	private static final Map<Integer, Set<Integer>> STAVES_BY_SPELLBOOK = ImmutableMap.of(
		SPELLBOOK_ANCIENT, ImmutableSet.of(
			ItemID.STAFF_OF_ZAROS, // Ancient staff
			ItemID.ANCIENT_SCEPTRE,
			ItemID.ANCIENT_SCEPTRE_TROUVER,
			ItemID.ANCIENT_SCEPTRE_BLOOD,
			ItemID.ANCIENT_SCEPTRE_BLOOD_TROUVER,
			ItemID.ANCIENT_SCEPTRE_ICE,
			ItemID.ANCIENT_SCEPTRE_ICE_TROUVER,
			ItemID.ANCIENT_SCEPTRE_SHADOW,
			ItemID.ANCIENT_SCEPTRE_SHADOW_TROUVER,
			ItemID.ANCIENT_SCEPTRE_SMOKE,
			ItemID.ANCIENT_SCEPTRE_SMOKE_TROUVER,
			ItemID.FROSTMOON_SPEAR, // Blue Moon spear
			ItemID.MAGICTRAINING_WAND_MASTER, // Master wand
			ItemID.KODAI_WAND,
			ItemID.DRAGONHUNTER_WAND,
			ItemID.NIGHTMARE_STAFF,
			ItemID.NIGHTMARE_STAFF_ELDRITCH,
			ItemID.NIGHTMARE_STAFF_VOLATILE,
			ItemID.WILD_CAVE_SCEPTRE_CHARGED_RECOL, // Thammaron's sceptre (a), charged
			ItemID.WILD_CAVE_ACCURSED_CHARGED_RECOL // Accursed sceptre (a), charged
		),
		SPELLBOOK_ARCEUUS, ImmutableSet.of(
			ItemID.BARROWS_AHRIM_WEAPON, // Ahrim's staff, undamaged
			ItemID.BARROWS_AHRIM_WEAPON_100,
			ItemID.BARROWS_AHRIM_WEAPON_75,
			ItemID.BARROWS_AHRIM_WEAPON_50,
			ItemID.BARROWS_AHRIM_WEAPON_25,
			ItemID.FROSTMOON_SPEAR, // Blue Moon spear
			ItemID.KODAI_WAND,
			ItemID.MAGICTRAINING_WAND_MASTER, // Master wand
			ItemID.PURGING_STAFF,
			ItemID.SOS_SKULL_SCEPTRE,
			ItemID.SOS_SKULL_SCEPTRE_IMBUED,
			ItemID.SLAYER_STAFF,
			ItemID.SLAYER_STAFF_ENCHANTED,
			ItemID.SOTD, // Staff of the Dead
			ItemID.TOXIC_SOTD, // Toxic staff of the dead, uncharged
			ItemID.TOXIC_SOTD_CHARGED // Toxic staff of the dead, charged
		)
	);

	public static boolean hasStaff(Client client, int spellbook)
	{
		if (spellbook == SPELLBOOK_STANDARD)
		{
			// way too many of these to list + everything can cast standards
			return isWieldingAutocastWeapon(client);
		}

		Set<Integer> staves = STAVES_BY_SPELLBOOK.getOrDefault(spellbook, ImmutableSet.of());
		return InventoryUtil.containsAny(client.getItemContainer(InventoryID.WORN), staves) ||
			InventoryUtil.containsAny(client, staves);
	}

	public static boolean isWieldingAutocastWeapon(Client client)
	{
		int weaponCategory = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
		int styleEnumId = client.getEnum(EnumID.WEAPON_STYLES).getIntValue(weaponCategory);
		if (styleEnumId == -1)
		{
			return false;
		}

		int[] styleStructs = client.getEnum(styleEnumId).getIntVals();
		if (styleStructs.length <= AutocastTracker.COM_MODE_CASTING)
		{
			return false;
		}

		StructComposition castingStyle = client.getStructComposition(styleStructs[AutocastTracker.COM_MODE_CASTING]);
		return CASTING_STYLE_NAME.equalsIgnoreCase(castingStyle.getStringValue(ParamID.ATTACK_STYLE_NAME));
	}

}

package com.duckblade.osrs.tfa.features.lobby;

import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.junit.jupiter.api.Assertions.assertEquals;

class EmptyNamesRemoverTest
{

	@Test
	void stripsBlankSlots()
	{
		assertEquals(
			"Shyphii<br>NTD<br>HR3<br>LlemonDuck",
			EmptyNamesRemover.stripBlankLines("Shyphii<br>NTD<br>HR3<br>LlemonDuck<br>-<br>-<br>-<br>-")
		);
	}

	@Test
	void keepsFullParty()
	{
		String full = "a<br>b<br>c<br>d<br>e<br>f<br>g<br>h";
		assertEquals(full, EmptyNamesRemover.stripBlankLines(full));
	}

	@Test
	void keepsHyphenatedNames()
	{
		assertEquals("a-b<br>-c", EmptyNamesRemover.stripBlankLines("a-b<br>-<br>-c<br>-"));
	}

	@Test
	void emptyPartyBecomesEmpty()
	{
		assertEquals("", EmptyNamesRemover.stripBlankLines("-<br>-<br>-<br>-<br>-<br>-<br>-<br>-"));
		assertEquals(0, EmptyNamesRemover.lineCount(""));
	}

	@Test
	void contentHeightShrinksPerMissingLine()
	{
		assertEquals(151, EmptyNamesRemover.contentHeight(8));
		assertEquals(151 - 4 * 15, EmptyNamesRemover.contentHeight(4));
		assertEquals(151 - 8 * 15, EmptyNamesRemover.contentHeight(0));
	}

	@Test
	void borderIsAnchoredRelativeToContent()
	{
		Widget content = Mockito.mock(Widget.class);
		Widget[] border = new Widget[8];
		for (int i = 0; i < border.length; i++)
		{
			border[i] = Mockito.mock(Widget.class);
			Mockito.when(content.getChild(i)).thenReturn(border[i]);
		}
		Mockito.when(content.getOriginalHeight()).thenReturn(151);

		EmptyNamesRemover.setContentHeight(content, 91);

		Mockito.verify(content).setOriginalHeight(91);
		Mockito.verify(content).revalidate();

		// bottom edge: hangs off the bottom, width follows the container
		Mockito.verify(border[1]).setOriginalY(-12);
		Mockito.verify(border[1]).setYPositionMode(WidgetPositionMode.ABSOLUTE_BOTTOM);
		Mockito.verify(border[1]).setOriginalWidth(32);
		Mockito.verify(border[1]).setWidthMode(WidgetSizeMode.MINUS);
		Mockito.verify(border[1]).setHeightMode(WidgetSizeMode.ABSOLUTE);

		// left and right edges: height follows the container, right is anchored right
		Mockito.verify(border[2]).setOriginalHeight(32);
		Mockito.verify(border[2]).setHeightMode(WidgetSizeMode.MINUS);
		Mockito.verify(border[3]).setOriginalHeight(32);
		Mockito.verify(border[3]).setHeightMode(WidgetSizeMode.MINUS);
		Mockito.verify(border[3]).setOriginalX(-12);
		Mockito.verify(border[3]).setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT);

		// bottom-right corner
		Mockito.verify(border[7]).setOriginalX(0);
		Mockito.verify(border[7]).setOriginalY(0);
		Mockito.verify(border[7]).setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT);
		Mockito.verify(border[7]).setYPositionMode(WidgetPositionMode.ABSOLUTE_BOTTOM);
	}

	@Test
	void borderUntouchedWhenHeightUnchanged()
	{
		Widget content = Mockito.mock(Widget.class);
		Mockito.when(content.getOriginalHeight()).thenReturn(91);

		EmptyNamesRemover.setContentHeight(content, 91);

		Mockito.verify(content, Mockito.never()).revalidate();
		Mockito.verify(content, Mockito.never()).getChild(Mockito.anyInt());
	}

}

package com.duckblade.osrs.tfa.features.loot;

import com.duckblade.osrs.tfa.TfaConfig;
import com.duckblade.osrs.tfa.util.RaidRoom;
import com.duckblade.osrs.tfa.util.RaidState;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.GroundObject;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GroundObjectSpawned;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class DryStreakTrackerTest
{

	private static final int STANDARD_FLAME = ObjectID.TFA_BRAZIER_GUTHIXLOOT01_FIRE01;
	private static final int PURPLE_FLAME = ObjectID.TFA_BRAZIER_GUTHIXLOOT01_FIRE02;
	private static final RaidState LOOT = RaidState.builder().inRaid(true).currentRoom(RaidRoom.LOOT).build();

	// TFA_VAULT_OWN_CHEST: 0 = no standard rewards chest assigned (own the unique chest), otherwise the chest number
	private static final int OWN_UNIQUE_CHEST = 0;
	private static final int OWN_STANDARD_CHEST = 3;

	@Mock
	Client client;

	@Mock
	TfaConfig config;

	@Mock
	ChatMessageManager chatMessageManager;

	DryStreakTracker tracker;

	@BeforeEach
	void setUp()
	{
		tracker = new DryStreakTracker(client, config, chatMessageManager);

		lenient().when(config.teamDryStreakTrackerEnabled()).thenReturn(true);
		lenient().when(config.personalDryStreakTrackerEnabled()).thenReturn(true);
		tracker.isEnabled(config, LOOT);
		tracker.startUp();
	}

	@Test
	void bothStreaksIncrementAfterTheDelayWhenStandardFlamesSpawn()
	{
		ownChest(OWN_STANDARD_CHEST);
		when(config.teamDryStreakCount()).thenReturn(7);
		when(config.personalDryStreakCount()).thenReturn(12);

		tracker.onGroundObjectSpawned(spawned(STANDARD_FLAME));
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS - 1);

		verify(config, never()).teamDryStreakCount(anyInt());
		verify(chatMessageManager, never()).queue(any(QueuedMessage.class));

		ticks(1);

		verify(config).teamDryStreakCount(8);
		verify(config).personalDryStreakCount(13);
		List<String> messages = queuedMessages();
		assertTrue(messages.get(0).startsWith("Team "));
		assertTrue(messages.get(0).contains("Dry Streak: <col=ff0000>8"));
		assertTrue(messages.get(1).startsWith("Personal "));
		assertTrue(messages.get(1).contains("Dry Streak: <col=ff0000>13"));
	}

	@Test
	void onlyTeamStreakEndsWhenPurpleBelongsToSomeoneElse()
	{
		ownChest(OWN_STANDARD_CHEST);
		when(config.teamDryStreakCount()).thenReturn(7);
		when(config.personalDryStreakCount()).thenReturn(12);

		tracker.onGroundObjectSpawned(spawned(PURPLE_FLAME));
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS);

		verify(config).teamDryStreakCount(0);
		verify(config).personalDryStreakCount(13);
		List<String> messages = queuedMessages();
		assertTrue(messages.get(0).contains("Dry Streak Ended: <col=ff0000>7"));
		assertTrue(messages.get(1).contains("Dry Streak: <col=ff0000>13"));
	}

	@Test
	void bothStreaksEndWhenOwnUniqueChest()
	{
		ownChest(OWN_UNIQUE_CHEST);
		when(config.teamDryStreakCount()).thenReturn(7);
		when(config.personalDryStreakCount()).thenReturn(41);

		tracker.onGroundObjectSpawned(spawned(PURPLE_FLAME));
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS);

		verify(config).teamDryStreakCount(0);
		verify(config).personalDryStreakCount(0);
		List<String> messages = queuedMessages();
		assertTrue(messages.get(0).contains("Dry Streak Ended: <col=ff0000>7"));
		assertTrue(messages.get(1).contains("Dry Streak Ended: <col=ff0000>41"));
	}

	@Test
	void ownChestIsReadWhenTheDelayEndsNotWhenTheFlamesSpawn()
	{
		ownChest(OWN_UNIQUE_CHEST);
		when(config.personalDryStreakCount()).thenReturn(5);

		tracker.onGroundObjectSpawned(spawned(PURPLE_FLAME));
		ticks(1);
		ownChest(OWN_STANDARD_CHEST);
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS - 1);

		verify(config).personalDryStreakCount(6);
	}

	@Test
	void personalStreakNeverEndsOnADryRaid()
	{
		ownChest(OWN_UNIQUE_CHEST);
		when(config.personalDryStreakCount()).thenReturn(5);

		tracker.onGroundObjectSpawned(spawned(STANDARD_FLAME));
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS);

		verify(config).personalDryStreakCount(6);
	}

	@Test
	void resolvesOnlyOncePerLootRoomVisit()
	{
		ownChest(OWN_STANDARD_CHEST);

		tracker.onGroundObjectSpawned(spawned(STANDARD_FLAME));
		ticks(1);
		tracker.onGroundObjectSpawned(spawned(STANDARD_FLAME));
		tracker.onGroundObjectSpawned(spawned(PURPLE_FLAME));
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS * 2);

		verify(config, times(1)).teamDryStreakCount(anyInt());
		verify(config, times(1)).personalDryStreakCount(anyInt());
		verify(chatMessageManager, times(2)).queue(any(QueuedMessage.class));

		tracker.startUp();
		tracker.onGroundObjectSpawned(spawned(STANDARD_FLAME));
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS);

		verify(config, times(2)).teamDryStreakCount(anyInt());
		verify(config, times(2)).personalDryStreakCount(anyInt());
	}

	@Test
	void leavingBeforeTheDelayEndsCancelsTheResolve()
	{
		tracker.onGroundObjectSpawned(spawned(STANDARD_FLAME));
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS - 1);

		tracker.startUp();
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS);

		verify(config, never()).teamDryStreakCount(anyInt());
		verify(chatMessageManager, never()).queue(any(QueuedMessage.class));
	}

	@Test
	void ignoresOtherObjects()
	{
		tracker.onGroundObjectSpawned(spawned(ObjectID.TFA_BRAZIER_GUTHIXLOOT01_BASE01));
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS);

		verify(config, never()).teamDryStreakCount(anyInt());
		verify(config, never()).personalDryStreakCount(anyInt());
		verify(chatMessageManager, never()).queue(any(QueuedMessage.class));
	}

	@Test
	void disabledStreakIsNeitherCountedNorReported()
	{
		when(config.teamDryStreakTrackerEnabled()).thenReturn(false);
		tracker.isEnabled(config, LOOT);
		ownChest(OWN_STANDARD_CHEST);
		when(config.personalDryStreakCount()).thenReturn(4);

		tracker.onGroundObjectSpawned(spawned(STANDARD_FLAME));
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS);

		verify(config, never()).teamDryStreakCount(anyInt());
		verify(config).personalDryStreakCount(5);
		verify(chatMessageManager, times(1)).queue(any(QueuedMessage.class));

		when(config.teamDryStreakTrackerEnabled()).thenReturn(true);
		when(config.personalDryStreakTrackerEnabled()).thenReturn(false);
		tracker.isEnabled(config, LOOT);
		tracker.startUp();

		tracker.onGroundObjectSpawned(spawned(STANDARD_FLAME));
		ticks(DryStreakTracker.RESOLVE_DELAY_TICKS);

		verify(config).teamDryStreakCount(1);
		verify(config, times(1)).personalDryStreakCount(anyInt());
		verify(chatMessageManager, times(2)).queue(any(QueuedMessage.class));
	}

	@Test
	void enabledWhenEitherStreakIsEnabled()
	{
		TfaConfig teamOnly = mock(TfaConfig.class);
		when(teamOnly.teamDryStreakTrackerEnabled()).thenReturn(true);
		TfaConfig personalOnly = mock(TfaConfig.class);
		when(personalOnly.personalDryStreakTrackerEnabled()).thenReturn(true);

		assertTrue(tracker.isEnabled(teamOnly, LOOT));
		assertTrue(tracker.isEnabled(personalOnly, LOOT));
		assertFalse(tracker.isEnabled(mock(TfaConfig.class), LOOT));
		assertFalse(tracker.isEnabled(teamOnly, LOOT.withSpectator(true)));
		assertFalse(tracker.isEnabled(teamOnly, LOOT.withCurrentRoom(RaidRoom.OCELLUS)));
	}

	private void ownChest(int varbitValue)
	{
		lenient().when(client.getVarbitValue(VarbitID.TFA_VAULT_OWN_CHEST)).thenReturn(varbitValue);
	}

	private void ticks(int count)
	{
		for (int i = 0; i < count; i++)
		{
			tracker.onGameTick(new GameTick());
		}
	}

	private GroundObjectSpawned spawned(int objectId)
	{
		GroundObject groundObject = mock(GroundObject.class);
		when(groundObject.getId()).thenReturn(objectId);

		GroundObjectSpawned e = new GroundObjectSpawned();
		e.setGroundObject(groundObject);
		return e;
	}

	private List<String> queuedMessages()
	{
		ArgumentCaptor<QueuedMessage> captor = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(chatMessageManager, times(2)).queue(captor.capture());
		return captor.getAllValues().stream()
			.map(QueuedMessage::getRuneLiteFormattedMessage)
			.collect(Collectors.toList());
	}

}

